# A runtime-name const_get dispatches over the constants its receiver can
# reach. The candidates were every constant of the program, in source
# order, cut at 512: past that a constant raised NameError where CRuby
# answers it. They are now those of the receiver, its ancestors and the
# modules they include, the top-level ones, and the class paths starting
# at one of them, with no cut. A constant only another module holds is
# CRuby's NameError, also for const_defined?, where it was answered.
TOP = :top
module Mixin
  MIX = :mix
end
class Base
  BASE = :base
end
module Away
  FAR = :far
  class Box; end
end
class Kid < Base
  include Mixin
  OWN = :own
  module Inner
    DEEP = :deep
  end
  def self.get(n) = const_get(n)
  def self.has(n) = const_defined?(n)
end
