def nm(s) = ARGV.size > 5 ? "x" : s
p Many.get(nm("C599")), Many.get(nm("C0")), Many.get(nm("C512"))
%w[OWN BASE MIX TOP Inner Away::Box].each { |n| p Kid.get(nm(n)) }
%w[FAR Box DEEP D3].each do |n|
  begin
    p Kid.get(nm(n))
  rescue NameError => e
    puts "NameError: #{e.message}"
  end
end
p %w[OWN FAR MIX Box].map { |n| Kid.has(nm(n)) }
p Object.const_get(nm("Away::Box")), Object.const_get(nm("TOP"))
begin
  Object.const_get(nm("FAR"))
rescue NameError => e
  puts "NameError: #{e.message}"
end
mod = ARGV.size > 5 ? Kid : Away
p mod.const_get(nm("FAR"))

class Table
  A_1 = 1
  A_2 = 2
  B_1 = 3
  def self.all(pat) = constants.grep(pat).sort.flat_map(&method(:const_get))
end
p Table.all(/^A_/)
